import React from 'react';

import { NavLink } from 'react-router-dom';

import { logout } from '@apps/Account/@services/authService';
import {
  getProfileInfo,
  updateCurrentUserFields,
  UserProfileDataPatch,
} from '@apps/Account/@services/user.service';
import { IUserProfileDTO } from '@apps/Account/@types/user.types';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import { changeAvatarInModal } from '@helpers/changeAvatarModal';
import notificationHelper from '@helpers/notificationHelper';
import nophoto from '@img/no_avatar.png';
import PohAlert from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { editProfileInModal } from './EditProfileModal';

const ProfileTabProfile = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [error, setIsError] = React.useState<Error>();
  const [profileData, setProfileData] = React.useState<IUserProfileDTO>();

  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const hd = await getProfileInfo();
        setProfileData(hd);
      } catch (e) {
        setIsError(e as Error);
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, []);

  if (isLoading) {
    return <PageLoader />;
  }

  if (error || !profileData) {
    return <PohAlert>{error?.message}</PohAlert>;
  }

  return (
    <div className="mt-3">
      <PohRow>
        <PohCol sm={5} md={3}>
          <img
            src={profileData.ava.length ? profileData.ava : nophoto}
            alt={[profileData.name, profileData.surname].join(' ')}
            className="img-thumbnail w-100"
          />

          <PohButton
            onClick={() =>
              changeAvatarInModal(
                {
                  title: 'Выбор лучшей фотки',
                  folder: `images/avatars/${profileData.id}/`,
                  width: 500,
                  height: 500,
                  name: `ava${new Date().toString().replace(/[^\da-zA-Z]+/g, '')}`,
                  sizes: [50, 100, 200],
                },
                async (src, saveres) => {
                  const patch: UserProfileDataPatch = {};

                  if (src) {
                    patch.ava = src;
                    patch.photo_max = src;
                    patch.photo_max_orig = src;
                    saveres?.sizes &&
                      Object.entries(saveres.sizes).forEach(([sizeKey, imageUrl]) => {
                        if (+sizeKey === 200) {
                          patch.ava = imageUrl;
                          patch.photo_200_orig = imageUrl;
                        } else {
                          patch[`photo_${sizeKey}` as keyof UserProfileDataPatch] = imageUrl;
                        }
                      });
                  } else {
                    Object.assign(patch, {
                      ava: '',
                      photo_50: '',
                      photo_100: '',
                      photo_200_orig: '',
                      photo_max: '',
                      photo_max_orig: '',
                    });
                  }
                  notificationHelper.success('Почти готово');
                  await updateCurrentUserFields(patch);
                  authContext.updateUser({ photo: src ?? undefined });
                  setProfileData((c) => ({ ...c, ...patch, ava: src }) as IUserProfileDTO);
                  notificationHelper.success('Ура. Новая фотка');
                },
              )
            }
            block
          >
            {profileData.ava.length > 0 ? 'Поменять фотку' : 'Выбрать фотку'}
          </PohButton>
        </PohCol>
        <PohCol sm={7} md={9}>
          <PohCard>
            <small className="text-muted">
              На сайте с {new Date(profileData.reg_date).toLocaleDateString()}
            </small>
            <h2 className="mt-0">
              {profileData.name} {profileData.surname}
            </h2>
            <h4>Дата рождения: {new Date(profileData.dob).toLocaleDateString()}</h4>
            <h4>Пол: {profileData.sex === '1' ? 'мужской' : 'женский'}</h4>
            {profileData.inaturalist_login?.length > 0 && (
              <p className="d-flex align-items-center" style={{ gap: 6, color: '#74ac00' }}>
                <img src="https://static.inaturalist.org/sites/1-favicon.png" width={16} />
                iNaturalist:
                <a
                  target="_blank"
                  referrerPolicy="no-referrer"
                  href={`https://inaturalist.org/people/${profileData.inaturalist_login}`}
                  rel="noreferrer"
                >
                  {profileData.inaturalist_login}
                </a>
              </p>
            )}

            <div className="border-top p-2 d-flex align-items-center">
              <NavLink to={`/user/${authContext.user?.id}`}>Ваша страница</NavLink>
              <PohButton
                onClick={() =>
                  editProfileInModal(profileData, (up) => {
                    (up.name || up.surname) &&
                      authContext.updateUser({ name: up.name, surname: up.surname });
                    setProfileData((c) => ({ ...c, ...up }) as IUserProfileDTO);
                    notificationHelper.success('Обновлено');
                  })
                }
                className="ms-auto"
              >
                Редактировать
              </PohButton>{' '}
              &nbsp;{' '}
              <PohButton
                onClick={() => {
                  logout(() => {
                    notificationHelper.success(`До новых встреч, ${profileData.name}`);
                    setTimeout(() => {
                      location.href = '/';
                    }, 2000);
                  });
                }}
              >
                Выйти
              </PohButton>
            </div>
          </PohCard>
        </PohCol>
      </PohRow>
    </div>
  );
};

export default ProfileTabProfile;
