import React from 'react';

import CheckCircleFill from '@pohodnik/icons/svg/Signs/CheckCircleFill';
import ExclamationDiamondFill from '@pohodnik/icons/svg/Signs/ExclamationDiamondFill';

import { getProvidersList } from '@apps/Account/@services/auth.services';
import { IAuthProviderDTO } from '@apps/Account/@types/auth.types';
import { addSocialAuthAsync } from '@apps/Account/Login/SocialAuth/socialAuthHelper';
import socialVisualizeResource, {
  AuthProvider,
} from '@apps/Account/Login/SocialAuth/socialVisualizeResource';
import { getLoginVariants, requestUserEmailConfirm } from '@apps/Users/@services/user.services';
import { IUserLoginVariant } from '@apps/Users/@types/user.types.dto';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import { addLoginPasswordLoginVariant } from './UserLoginLoginPasswordModal';

const UserLoginVariants = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IUserLoginVariant[]>([]);
  const [providers, setProviders] = React.useState<IAuthProviderDTO[]>([]);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getLoginVariants();
      setData(res);
      const res1 = await getProvidersList();
      setProviders(res1);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PohLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const handleAdd = async () => {
    try {
      await addLoginPasswordLoginVariant();
      notificationHelper.success('Добавлено');
      load();
    } catch (error) {
      notificationHelper.error((error as Error).message);
    }
  };

  return (
    <div>
      <PohList
        data={data.map((r) => {
          return {
            key: r.id,
            children: (
              <PohRow>
                <PohCol sm="6" as="strong">
                  {r.login || r.email || r.social_id}
                </PohCol>
                <PohCol sm="4" xs={8} className="d-flex justify-content-end align-items-center">
                  {r.confirmed_at && (
                    <small className="text-success ms-auto">
                      &nbsp;&nbsp;
                      <CheckCircleFill />
                      &nbsp;Подтверждён {new Date(r.confirmed_at).toLocaleString()}
                    </small>
                  )}
                  {r.email && r.email.includes('@') && !r.confirmed_at && (
                    <strong className="text-warning">
                      &nbsp;
                      <ExclamationDiamondFill />
                      &nbsp;
                      <small>Необходимо подтверждение email</small>
                      &nbsp;
                      <PohButton
                        size={ButtonSize.Small}
                        variant={ButtonVariant.OutlineWarning}
                        className="py-0"
                        onClick={async (e) => {
                          const btn = e.target as HTMLButtonElement;
                          try {
                            btn.disabled = true;
                            await requestUserEmailConfirm(+r.id);
                            notificationHelper.success(`Код отправлен на почту ${r.email}`);
                          } catch (error) {
                            notificationHelper.error((error as Error).message);
                          } finally {
                            btn.disabled = false;
                          }
                        }}
                      >
                        Подтвердить
                      </PohButton>
                      &nbsp;{r.created_at && <small>Отправлено: {r.created_at}</small>}
                    </strong>
                  )}
                </PohCol>
                <PohCol sm="2" xs={4} className="text-end">
                  <small>{r.provider || r.network}</small>
                </PohCol>
              </PohRow>
            ),
          };
        })}
      />
      <div className="mt-2 d-flex align-items-center">
        <small className="text-info text-end pe-3 me-3 border-end" style={{ lineHeight: 1 }}>
          Добавьте удобный
          <br />
          способ авторизации
        </small>
        <PohButton
          variant={ButtonVariant.OutlineInfo}
          size={ButtonSize.Small}
          className="me-2"
          onClick={handleAdd}
        >
          Логин/Пароль
        </PohButton>
        {providers.map((x) => {
          const { iconComponent: Icon, bg, name } = socialVisualizeResource[x.id as AuthProvider];
          return (
            <PohButton
              key={x.id}
              type="button"
              title={name}
              style={{
                backgroundColor: bg,
                padding: '6px',
                lineHeight: '20px',
                borderRadius: '2px',
                margin: '2px',
              }}
              onClick={(e) => {
                e.preventDefault();
                addSocialAuthAsync({ url: x.url } as any).then(() => {
                  load();
                });
              }}
            >
              <Icon style={{ fill: 'white', width: 20, height: 20 }} />
            </PohButton>
          );
        })}
      </div>
    </div>
  );
};

export default UserLoginVariants;
