import React from 'react';

import clsx from 'clsx';
import { UAParser } from 'ua-parser-js';

import { logout } from '@apps/Account/@services/authService';
import {
  getAccountSessions,
  IAccountSession,
  killAccountSessions,
} from '@apps/Users/@services/user.services';
import PageLoader from '@components/PageLoader';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

const ProfileTabSessions = () => {
  const [loading, setLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IAccountSession[]>([]);

  const start = React.useCallback(async () => {
    try {
      setLoading(true);
      const d = await getAccountSessions();
      setData(d);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setLoading(false);
    }
  }, []);
  React.useEffect(() => {
    start();
  }, []);

  if (loading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const now = new Date().getTime();

  const handleLogout = () => {
    logout(() => {
      notificationHelper.success(`До новых встреч`);
      setTimeout(() => {
        location.href = '/';
      }, 2000);
    });
  };
  return (
    <section>
      <PohRow className="mt-3">
        <PohCol sm={12}>
          <h3>
            <PohButton className="float-end" onClick={handleLogout}>
              Выйти
            </PohButton>
            Сессии
          </h3>
        </PohCol>
      </PohRow>
      {data == null && <PageLoader />}
      {data && data.length === 0 && <Empty>Нет Сессий</Empty>}
      {data && data.length > 0 && (
        <PohList
          data={data.map((row) => {
            let ua: React.ReactNode = null;

            if (row.user_agent) {
              const { browser, cpu, device, os } = UAParser(row.user_agent);
              ua = (
                <span>
                  {browser.type}
                  {browser.name} {browser.major} на {device.vendor} {device.model} {device.type} (
                  {os.name} {os.version} {cpu.architecture})
                </span>
              );
            }

            return {
              key: row.id,
              content: (
                <div
                  className={clsx(
                    'd-flex my-n1 align-items-center',
                    row.hash.includes('revoked') && 'text-muted',
                  )}
                  style={{ gap: 10 }}
                >
                  <strong>{row.date_start}</strong>
                  {row.hash.includes('revoked') && (
                    <small className="text-danger">{row.hash}</small>
                  )}
                  {document.cookie.includes(row.hash) && (
                    <small className="text-success">Текущая сессия</small>
                  )}
                  &nbsp;
                  {row.ip}
                  <em className="ms-auto">
                    <small title={row.user_agent ?? ''}>{ua}</small>
                  </em>
                  {now - new Date(row.date_start).getTime() < 86400000 * 7 &&
                    !row.hash.includes('revoked') && (
                      <PohButton
                        onClick={() => {
                          document.cookie.includes(row.hash) && handleLogout();

                          killAccountSessions(+row.id).then(() => {
                            notificationHelper.success('Сессия убита');
                            start();
                          });
                        }}
                      >
                        Убить сессию
                      </PohButton>
                    )}
                </div>
              ),
            };
          })}
        />
      )}
    </section>
  );
};

export default ProfileTabSessions;
