import React from 'react';

import PohContainer from '@ui-kit/layout/Container';
import PohTabs from '@ui-kit/Tabs';

import { profileTabs } from './profileTabs';

const ProfilePage: React.FC = () => {
  return (
    <PohContainer>
      <PohTabs useHash tabs={profileTabs} />
    </PohContainer>
  );
};

export default ProfilePage;
