import React from 'react';

import { IUserAllergies } from '@apps/Users/@types/user.types';
import PohButton from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';

interface IUserAllergiesListItemProps {
  data: IUserAllergies;
  onChange?: (item: IUserAllergies) => void;
}

const UserAllergiesListItem: React.FC<IUserAllergiesListItemProps> = ({ data, onChange }) => {
  return (
    <div className="toolbared">
      <aside className="show-on-hover float-end">
        {onChange && <PohButton icon={IconsEnum.edit} onClick={() => onChange(data)} />}
      </aside>
      <h5 className="list-group-item-heading mb-1">{data.name}</h5>
      <p className="list-group-item-text mb-1">
        <small>{data.comment}</small>
      </p>
    </div>
  );
};

export default UserAllergiesListItem;
