import React, { FormEvent } from 'react';

import { addLoginVariantLoginPassword } from '@apps/Users/@services/user.services';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

interface IUserLoginLoginPasswordModalProps {
  onSave: () => void;
  onCancel: () => void;
}

const UserLoginLoginPasswordModal: React.FC<IUserLoginLoginPasswordModalProps> = ({
  onCancel,
  onSave,
}) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState({
    login: '',
    password: '',
    password1: '',
  });

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      setIsLoading(true);
      if (data.password !== data.password1) {
        notificationHelper.warning('Пароли не совпадают');
        return;
      }
      await addLoginVariantLoginPassword(data);
      onSave();
    } catch (er) {
      setErr(er as Error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    onCancel();
  };

  return (
    <form
      onSubmit={handleSubmit}
      onReset={handleReset}
      className="d-flex flex-column"
      style={{ gap: 12 }}
    >
      <PohInput
        label="Логин"
        title="латинские буквы, цифры, символы @, ., - и _"
        pattern="^[a-z]+([-_@.]?[a-z0-9]+){0,2}$"
        placeholder="Введите логин"
        value={data.login}
        onChange={(v) => setData((c) => ({ ...c, login: v }))}
        required
        disabled={isLoading}
      />
      <PohInput
        label="Пароль"
        type={InputTypes.password}
        pattern=".{4,}"
        placeholder="Введите пароль"
        value={data.password}
        onChange={(v) => setData((c) => ({ ...c, password: v }))}
        required
        disabled={isLoading}
      />
      <PohInput
        label="Пароль еще раз"
        type={InputTypes.password}
        pattern=".{4,}"
        placeholder="Введите пароль ещё раз"
        value={data.password1}
        onChange={(v) => setData((c) => ({ ...c, password1: v }))}
        required
        disabled={isLoading}
      />
      {err && (
        <PohAlert variant={AlertVariant.Danger} className="my-2">
          {err.message}
        </PohAlert>
      )}
      <PohRow>
        <PohCol sm={12} className="text-end">
          <PohButton type="reset" className="me-2" disabled={isLoading}>
            Отмена
          </PohButton>
          <PohButton type="submit" variant={ButtonVariant.Primary} disabled={isLoading}>
            Сохранить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export default UserLoginLoginPasswordModal;

export const addLoginPasswordLoginVariant = (): Promise<void> => {
  return new Promise((res) => {
    showModal({
      title: 'Введите логин и пароль',
      children: (clos) => (
        <UserLoginLoginPasswordModal
          onSave={() => {
            clos();
            res();
          }}
          onCancel={() => {
            clos();
          }}
        />
      ),
    });
  });
};
