import React from 'react';

import PageLoader from '@components/PageLoader';
import { success } from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import { confirmModal } from '@ui-kit/Modal';

import { addPhoneModal } from './addPhone/addPhoneModal';
import { editPhoneModal } from './addPhone/editPhoneModal';
import { deleteUserPhone, getUserPhones, testUserPhone } from '../@services/user.service';
import { IUserPhone } from '../@types/user.types';

const Phones = () => {
  const [loading, setLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IUserPhone[]>([]);
  React.useEffect(() => {
    const start = async () => {
      try {
        setLoading(true);
        const d = await getUserPhones();
        setData(d);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setLoading(false);
      }
    };
    start();
    getUserPhones().then(setData);
  }, []);

  if (loading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const handleAdd = () => addPhoneModal((res) => setData([...data, res]));

  const handleEdit = (row: IUserPhone) => () =>
    editPhoneModal(row, (res) => {
      setData(data.map((x) => (+x.id === +row.id ? { ...x, ...res } : x)));
    });

  const handleDel = (row: IUserPhone) => () => {
    confirmModal({ children: `Точно удалить ${row.phone}?` }).then(() => {
      deleteUserPhone(row.id).then((res) => {
        if (res.success) {
          setData(data.filter((x) => +x.id !== +row.id));
          success('Удалено');
        }
      });
    });
  };

  const handleTest = (row: IUserPhone) => () => {
    confirmModal({
      children: `Отправить тестовое СМС сообщение на номер ${row.phone}?`,
      confirmText: 'Отправить',
    }).then((isOk) => {
      isOk &&
        testUserPhone(row.id).then((res) => {
          if (res) {
            success(`Отправлено ${res.status} / Доступно ${res.balance}₽`, { duration: 5000 });
          }
        });
    });
  };

  return (
    <section>
      <PohRow className="mt-3">
        <PohCol sm={6}>
          <h3>Телефоны</h3>
        </PohCol>
        <PohCol sm={6} className="text-end">
          <PohButton onClick={handleAdd}>Добавить телефон</PohButton>
        </PohCol>
      </PohRow>
      <p>
        Добавьте номера телефонов. Так-же можно настроить интеграцию с{' '}
        <a href="http://sms.ru" target="_blank" rel="noreferrer">
          sms.ru
        </a>
        , для этого нужно скопировать token полученый после регистрации и вставить его в поле API
        key
      </p>
      {data == null && <PageLoader />}
      {data && data.length === 0 && <Empty>Нет телефонов</Empty>}
      {data && data.length > 0 && (
        <PohList
          data={data.map((row) => ({
            key: row.id,
            content: (
              <div className="d-flex my-n1 justify-content-between align-items-center">
                <div>
                  <strong>{row.phone}</strong>
                  &nbsp;
                  {row.is_contact && <PohBadge variant={BadgeVariant.Info}>Контактный</PohBadge>}
                  &nbsp;
                  {row.is_send_sms && <PohBadge variant={BadgeVariant.Warning}>СМС</PohBadge>}
                  &nbsp;&nbsp;
                  {row?.sms_api_key?.length > 0 && (
                    <em>
                      <small>{`${row.sms_api_key.substr(0, 10)}******${row.sms_api_key.substr(-7)}`}</small>
                    </em>
                  )}
                </div>
                <div>
                  {row.is_send_sms && row?.sms_api_key?.length > 0 && (
                    <PohButton
                      variant={ButtonVariant.Light}
                      size={ButtonSize.Small}
                      onClick={handleTest(row)}
                      title="Проверить отправку смс"
                      className="me-2"
                    >
                      <small className="text-success">Проверить</small>
                    </PohButton>
                  )}
                  <PohButton
                    icon={IconsEnum.trash}
                    size={ButtonSize.Small}
                    onClick={handleDel(row)}
                  />
                  <PohButton
                    icon={IconsEnum.edit}
                    size={ButtonSize.Small}
                    onClick={handleEdit(row)}
                  />
                </div>
              </div>
            ),
          }))}
        />
      )}
    </section>
  );
};

export default Phones;
