import React from 'react';

import {
  getSubscribesList,
  testSubscribeById,
  toggleUserSubscribe,
} from '@apps/Users/@services/subscribes.services';
import { IUserSubscribeListItem } from '@apps/Users/@types/user.types';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import { addUserSubscribe } from './SubscribeAddModal';

const ProfileTabSubscribes = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IUserSubscribeListItem[]>([]);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getSubscribesList();
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PohLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const handleToggleSubscribe = (id: number, on: boolean) => {
    try {
      notificationHelper.success(on ? 'Подписка активирована.' : 'Подписка приостановлена.');
      toggleUserSubscribe(id, on);
      setData((x) => x.map((s) => (s.id === id ? { ...s, is_active: on } : s)));
    } catch (error) {
      notificationHelper.error((error as Error).message);
    }
  };

  const handleAdd = () => {
    addUserSubscribe();
    load();
  };

  return (
    <div className="pt-3">
      <h3>
        <div className="float-end">
          <PohButton size={ButtonSize.Small} variant={ButtonVariant.Success} onClick={handleAdd}>
            Добавить
          </PohButton>
        </div>
        Подписки
      </h3>
      <p>
        В этом разделе вы можете настроить подписки чтобы получать уведомления о новых походах на
        e-mail.
      </p>
      <PohList
        data={data.map((s) => {
          const handleTest = () => {
            testSubscribeById(s.id);
          };
          return {
            key: s.id,
            children: (
              <>
                <h5 className="list-group-item-heading mb-1">
                  <span className="float-end d-flex" style={{ gap: 12 }}>
                    {s.confirm_date && (
                      <small className={s.is_active ? 'text-success' : 'text-warning'}>
                        {s.is_active ? 'Подписка активна' : 'Подписка приостановлена'}
                      </small>
                    )}
                    {!s.confirm_date && (
                      <small className={s.confirm_date ? 'text-success' : 'text-danger'}>
                        {!s.confirm_date ? 'Ожидается подтверждение email' : ''}
                      </small>
                    )}
                    <strong>
                      <PohCheckbox
                        onChange={(val) => {
                          handleToggleSubscribe(s.id, val);
                        }}
                        checked={s.is_active}
                      />
                    </strong>
                  </span>
                  {s.email}
                </h5>
                <div className="list-group-item-text mb-1">
                  <div>
                    <div>
                      <span className="text-muted">Регионы: </span>
                      {s.regions.length === 0
                        ? 'Все регионы'
                        : s.regions.map((r) => r.name).join(',  ')}
                    </div>
                    <div>
                      <span className="text-muted">Типы: </span>
                      {s.types.length === 0 ? 'Все типы' : s.types.map((r) => r.name).join(',  ')}
                    </div>
                    {s.confirm_date && (
                      <small className="float-end pull-right">
                        <PohButton size={ButtonSize.Small} onClick={handleTest}>
                          test
                        </PohButton>
                      </small>
                    )}
                  </div>
                </div>
              </>
            ),
          };
        })}
      />
    </div>
  );
};

export default ProfileTabSubscribes;
