import { IUserPhone } from '@apps/Account/@types/user.types';
import { showModal } from '@ui-kit/Modal';

import AddPhoneModal from './components/AddPhoneModal';

export function addPhoneModal(onAdd: (d: IUserPhone) => void) {
  showModal({
    children: (closeHandler) => (
      <AddPhoneModal
        onSave={(newItem) => {
          onAdd(newItem);
          closeHandler();
        }}
        onCancel={closeHandler}
      />
    ),
  });
}

export default { addPhoneModal };
