import React from 'react';

import { selectProductAsync } from '@apps/Products/components/ProductSelectModal/productSelectModalHelper';
import {
  addUserAllergy,
  deleteUserAllergy,
  updateUserAllergy,
} from '@apps/Users/@services/userAllergies.services';
import { IUserAllergies, UserAllergiesType } from '@apps/Users/@types/user.types';
import { selectMedicamentAsync } from '@components/MedicamentSelector';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohContainer from '@ui-kit/layout/Container';
import { showModal } from '@ui-kit/Modal';

interface IUserAllergyEditModalProps {
  data: IUserAllergies;
  onSave: (d: IUserAllergies) => void;
  onCancel: () => void;
  onDelete?: () => void;
}

const UserAllergyEditModal: React.FC<IUserAllergyEditModalProps> = ({
  data,
  onSave,
  onCancel,
  onDelete,
}) => {
  const [modelData, setModelData] = React.useState<IUserAllergies>(data);
  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (modelData.id > 0) {
      await updateUserAllergy(modelData);
      onSave({ ...modelData, updated_at: new Date() });
    } else {
      const id = await addUserAllergy(modelData);
      onSave({ ...modelData, created_at: new Date(), id });
    }
  };

  function handleChange<k extends keyof IUserAllergies>(fieldName: k) {
    return (value: IUserAllergies[k]) => setModelData((cur) => ({ ...cur, [fieldName]: value }));
  }

  const handleDelete = async () => {
    if (!onDelete || !confirm('Удалить?')) return;
    await deleteUserAllergy(modelData.id);
    onDelete();
  };

  return (
    <PohContainer as="form" onSubmit={handleSave}>
      {modelData.type === UserAllergiesType.Other && (
        <PohInput
          label="Название"
          value={modelData.name}
          maxLength={64}
          onChange={handleChange('name')}
          required
        />
      )}
      {modelData.type === UserAllergiesType.Medicament && (
        <PohInput
          label="Медикамент"
          placeholder="Выберите медикамент"
          defaultValue={modelData.medicament?.name ?? ''}
          onFocus={async (e) => {
            (e.target as HTMLInputElement).blur();
            const medicament = await selectMedicamentAsync();
            handleChange('name')(medicament.name);
            handleChange('medicament')({ id: medicament.id, name: medicament.name });
          }}
          required
        />
      )}
      {modelData.type === UserAllergiesType.Product && (
        <PohInput
          label="Продукт"
          placeholder="Выберите продукт"
          defaultValue={modelData.product?.name ?? ''}
          onFocus={async (e) => {
            (e.target as HTMLInputElement).blur();
            const product = await selectProductAsync();
            handleChange('name')(product.name);
            handleChange('product')({ id: product.id, name: product.name });
          }}
          required
        />
      )}
      <PohInput
        label="Комментарий"
        value={modelData.comment}
        onChange={handleChange('comment')}
        required
        type={InputTypes.textarea}
      />

      <footer className="mt-4 d-flex">
        {onDelete && <PohButton icon={IconsEnum.trash} onClick={handleDelete} />}
        <PohButton variant={ButtonVariant.Secondary} onClick={onCancel} className="ms-auto">
          Отмена
        </PohButton>{' '}
        &nbsp;
        <PohButton variant={ButtonVariant.Primary} type="submit">
          Сохранить
        </PohButton>
      </footer>
    </PohContainer>
  );
};

export default UserAllergyEditModal;

export const editUserAllergy = (
  cur: IUserAllergies,
  cb: (up: IUserAllergies) => void,
  cbDel?: () => void,
) =>
  showModal({
    style: { minWidth: 380 },
    title: cur.id > 0 ? 'Редактирование аллергии' : 'Добавление аллергии',
    children: (clos) => (
      <UserAllergyEditModal
        data={cur}
        onCancel={clos}
        onSave={(up) => {
          cb(up);
          clos();
        }}
        onDelete={
          cbDel
            ? () => {
                cbDel();
                clos();
              }
            : undefined
        }
      />
    ),
  });
