import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import UserLoginVariants from './UserLoginVariants';

const ProfileTabInvariants = () => {
  return (
    <div className="py-3">
      <h3>Управление способами входа в аккаунт.</h3>
      <p>
        <small>
          Вы можете добавить способы входа. Например через социальную сеть или пару логин/пароль. Вы
          будете попадать в один аккаунт.
        </small>
      </p>

      <PohRow>
        <PohCol sm={12}>
          <UserLoginVariants />
        </PohCol>
      </PohRow>
    </div>
  );
};

export default ProfileTabInvariants;
