import React from 'react';

import { IHikingType } from '@apps/Hiking/@types/hiking.types';
import { IGeoRegion } from '@apps/Routes/@services/geo.services';
import { addSubscribes, requestConfirmSubscribe } from '@apps/Users/@services/subscribes.services';
import { selectGeoRegionsSeveralAsync } from '@components/GeoRegionSelector';
import { selectHikingTypesSeveralAsync } from '@components/HikingTypeSelector';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import { showModal } from '@ui-kit/Modal';

const SubscribeAddModal = ({ onComplete }: { onComplete: () => void }) => {
  const [isSaving, setIsSaving] = React.useState(false);
  const [email, setEmail] = React.useState('');
  const [regions, setRegions] = React.useState<IGeoRegion[]>([]);
  const [types, setTypes] = React.useState<IHikingType[]>([]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      setIsSaving(true);
      const { id } = await addSubscribes({
        email,
        regions: regions.map((d) => d.id),
        types: types.map((d) => d.id),
      });
      await requestConfirmSubscribe(id);
      onComplete();
      notificationHelper.success('Добавлено');
    } catch (err) {
      notificationHelper.error((err as Error).message);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <PohInput
        name="email"
        label="E-mail"
        placeholder="yalta89@mail.ru"
        required
        autoFocus
        type={InputTypes.email}
        disabled={isSaving}
        onChange={setEmail}
        value={email}
      />
      <PohInput
        onClick={async () => {
          const rg = await selectGeoRegionsSeveralAsync({
            selected: regions.map((d) => d.id),
            everyoneIsNobody: true,
          });
          setRegions(rg);
        }}
        placeholder="Все регионы"
        name="regions"
        label="Регионы"
        disabled={isSaving}
        value={regions.map((r) => r.name).join(', ')}
        title={regions.map((r) => r.name).join(',\n')}
        readOnly
      />

      <PohInput
        onClick={async () => {
          const rg = await selectHikingTypesSeveralAsync({
            selected: types.map((d) => d.id),
            everyoneIsNobody: true,
          });
          setTypes(rg);
        }}
        placeholder="Все типы"
        name="types"
        label="Типы"
        disabled={isSaving}
        value={types.map((r) => r.name).join(', ')}
        title={types.map((r) => r.name).join(',\n')}
        readOnly
      />

      <PohButton
        variant={ButtonVariant.Primary}
        type="submit"
        disabled={isSaving}
        value="Подписаться"
        block
      />
    </form>
  );
};
export default SubscribeAddModal;

export const addUserSubscribe = (): Promise<void> => {
  return new Promise((res) => {
    showModal({
      children: (clos) => (
        <SubscribeAddModal
          onComplete={() => {
            clos();
            res();
          }}
        />
      ),
    });
  });
};
